use super::*;
use crate::money::Money;

/// The figure `runway` asks for: what an ordinary month costs BEYOND the standing obligations.
///
/// Fixed spending is deliberately NOT included — the obligation calendar already carries it, and a
/// runway that subtracted both would double-count every subscription it knows about.
pub fn discretionary_monthly(s: &SpendingAnalysis) -> Money {
    s.variable_monthly
}
